161→    /// Generate a summary line for display.
162→    pub fn summary_line(&self) -> String {
163→        let status = self.status();
164→        let duration_str = format_duration(self.duration);
165→
166→        match status {
167→            StepStatus::Completed => {
168→                format!("{} {} ({})", status.display_char(), self.name, duration_str)
169→            }
170→            StepStatus::Skipped => {
171→                let reason = self
172→                    .check_result
173→                    .as_ref()
174→                    .map(|c| c.short_description())
175→                    .unwrap_or("already complete");
176→                format!("{} {} ({})", status.display_char(), self.name, reason)
177→            }
178→            StepStatus::Failed => {
179→                let error = self.error.as_deref().unwrap_or("unknown error");
180→                format!("{} {} - {}", status.display_char(), self.name, error)
181→            }
182→            _ => format!("{} {}", status.display_char(), self.name),
183→        }
184→    }
185→}
186→
187→fn format_duration(duration: Duration) -> String {
188→    let secs = duration.as_secs();
189→    let millis = duration.subsec_millis();
190→
191→    if secs == 0 {
192→        format!("{}ms", millis)
193→    } else if secs < 60 {
194→        format!("{}.{}s", secs, millis / 100)
195→    } else {
196→        let mins = secs / 60;
197→        let secs = secs % 60;
198→        format!("{}m {}s", mins, secs)
199→    }
200→}
