 16→/// Use [`short_description`](CheckResult::short_description) to get a
 17→/// display-friendly form with prefixes like "Command succeeded:" stripped.
 18→#[derive(Debug, Clone)]
 19→pub struct CheckResult {
 20→    /// Whether the check passed (step is complete).
 21→    pub complete: bool,
 22→
 23→    /// Description of what was checked.
 24→    pub description: String,
 25→
 26→    /// Details about the check result.
 27→    pub details: Option<String>,
 28→}
 29→
 30→impl CheckResult {
 31→    /// Create a complete result.
 32→    pub fn complete(description: impl Into<String>) -> Self {
 33→        Self {
 34→            complete: true,
 35→            description: description.into(),
 36→            details: None,
 37→        }
 38→    }
 39→
 40→    /// Get a short, display-friendly description with common prefixes stripped.
 41→    ///
 42→    /// Strips prefixes like "Command succeeded: ", "File exists: " etc.
 43→    /// Returns the original description if no prefix is found.
 44→    pub fn short_description(&self) -> &str {
 45→        const PREFIXES: &[&str] = &[
 46→            "Command succeeded: ",
 47→            "Command failed: ",
 48→            "File exists: ",
 49→            "File missing: ",
 50→            "Check passed: ",
 51→        ];
 52→        for prefix in PREFIXES {
 53→            if let Some(rest) = self.description.strip_prefix(prefix) {
 54→                return rest;
 55→            }
 56→        }
 57→        &self.description
 58→    }
 59→
 60→    /// Create an incomplete result.
 61→    pub fn incomplete(description: impl Into<String>, details: impl Into<String>) -> Self {
 62→        Self {
 63→            complete: false,
 64→            description: description.into(),
 65→            details: Some(details.into()),
 66→        }
 67→    }
 68→}
