 70→/// Run a completed check.
 71→pub fn run_check(check: &CompletedCheck, project_root: &Path) -> CheckResult {
 72→    match check {
 73→        CompletedCheck::FileExists { path } => check_file_exists(path, project_root),
 74→        CompletedCheck::CommandSucceeds { command } => {
 75→            check_command_succeeds(command, project_root)
 76→        }
 77→        CompletedCheck::Marker => check_marker(project_root),
 78→        CompletedCheck::All { checks } => check_all(checks, project_root),
 79→        CompletedCheck::Any { checks } => check_any(checks, project_root),
 80→    }
 81→}
 82→
 83→/// Run a completed check with variable interpolation.
 84→///
 85→/// Command strings in `CommandSucceeds` checks are resolved through the
 86→/// interpolation context before execution. File paths and other fields
 87→/// are not interpolated.
 88→pub fn run_check_interpolated(
 89→    check: &CompletedCheck,
 90→    project_root: &Path,
 91→    context: &InterpolationContext,
 92→) -> Result<CheckResult> {
 93→    match check {
 94→        CompletedCheck::CommandSucceeds { command } => {
 95→            let resolved = resolve_string(command, context)?;
 96→            Ok(check_command_succeeds(&resolved, project_root))
 97→        }
 98→        CompletedCheck::FileExists { path } => Ok(check_file_exists(path, project_root)),
 99→        CompletedCheck::Marker => Ok(check_marker(project_root)),
100→        CompletedCheck::All { checks } => {
101→            let mut results = Vec::new();
102→            for c in checks {
103→                results.push(run_check_interpolated(c, project_root, context)?);
104→            }
105→            if results.iter().all(|r| r.complete) {
106→                Ok(CheckResult::complete(format!(
107→                    "All {} checks passed",
108→                    checks.len()
109→                )))
110→            } else {
111→                let failed: Vec<_> = results
112→                    .iter()
113→                    .filter(|r| !r.complete)
114→                    .map(|r| r.description.clone())
115→                    .collect();
116→                Ok(CheckResult::incomplete(
117→                    format!("{}/{} checks failed", failed.len(), checks.len()),
118→                    failed.join("; "),
119→                ))
120→            }
121→        }
122→        CompletedCheck::Any { checks } => {
123→            let mut results = Vec::new();
124→            for c in checks {
125→                results.push(run_check_interpolated(c, project_root, context)?);
126→            }
127→            if let Some(passed) = results.iter().find(|r| r.complete) {
128→                Ok(CheckResult::complete(format!(
129→                    "Check passed: {}",
130→                    passed.description
131→                )))
132→            } else {
133→                Ok(CheckResult::incomplete(
134→                    format!("None of {} checks passed", checks.len()),
135→                    results
136→                        .iter()
137→                        .map(|r| r.description.clone())
138→                        .collect::<Vec<_>>()
139→                        .join("; "),
140→                ))
141→            }
142→        }
143→    }
144→}
